'use strict';
const $ = (id) => document.getElementById(id);
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state = {collections:[], loaded:false, collectionError:'', jobs:new Map(), ignoredJobs:new Set(), removedCollections:new Set(), sources:new Map(), sourceUploads:new Map(), oneTimeSources:new Map(), sourceDrafts:new Map(), sourceHistoryErrors:new Set(), sourceRuns:new Map(), sourceErrors:new Map(), selected:new Set(), query:'', mode:'search', backend:'elasticsearch', result:null, searching:false, searchError:'', collectionLoading:false, searchAbort:null, searchStage:''};
const terminal = (status) => ['completed','complete','succeeded','success','failed','cancelled','partial','partial_success'].includes(status);
const path = (id) => '/api/collections/' + encodeURIComponent(id);
const route = () => { const [view='collections', id=''] = location.hash.slice(1).split('/'); return {view, id:decodeURIComponent(id)}; };
const current = () => state.collections.find(c => String(c.id) === route().id);
const link = (view,id='') => '#' + view + (id ? '/' + encodeURIComponent(id) : '');
function message(text='', error=false) { $('notice').textContent=text; $('notice').className=error?'error':''; }
async function api(url, options={}) {
  const response=await fetch(url,{...options,headers:options.body instanceof FormData ? options.headers : {'Content-Type':'application/json',...options.headers}});
  let data; try { data=await response.json(); } catch { if(!response.ok) throw new Error('Request failed ('+response.status+'). Try again.'); data={}; }
  if(!response.ok){const error=new Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail||data.error||'Request failed ('+response.status+').'));error.status=response.status;throw error;}
  return data;
}
function badge(status) { const value=String(status||'unknown'); const kind=/fail|error/.test(value)?'failed':/pending|process|queue|running|index|delet|promot/.test(value)?'pending':/partial/.test(value)?'attention':''; return `<span class="status ${kind}">${esc(value.replaceAll('_',' '))}</span>`; }
function heading(title,copy,actions='') {return `<div class="heading"><div><h1>${esc(title)}</h1><p>${esc(copy)}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;}
function unavailable() {return `<div class="surface empty"><h2>${state.loaded?'Collection unavailable':'Loading collection…'}</h2><p>${state.loaded?'The collection may have been deleted. Return to your collections to continue.':'Fetching collection details.'}</p>${state.loaded?'<a class="btn" href="#collections">View collections</a>':''}</div>`;}
async function refreshCollections({renderView=false}={}) {
  if(state.collectionLoading) return;
  state.collectionLoading=true;
  try {const data=await api('/api/collections'); const changed=!state.loaded||Boolean(state.collectionError)||JSON.stringify(state.collections)!==JSON.stringify(data.collections||[]); state.collections=(data.collections||[]).filter(c=>!state.removedCollections.has(String(c.id)));for(const [id,job] of state.jobs)if(job.collection_id&&!state.collections.some(c=>String(c.id)===String(job.collection_id)))retireJob(id); state.loaded=true; state.collectionError=''; for(const id of state.selected) if(!state.collections.some(c=>String(c.id)===id)) state.selected.delete(id);
    if(renderView||(changed&&['collections','collection','activity'].includes(route().view))) render(); else updateScope();if(['collection','activity','job'].includes(route().view))for(const job of state.jobs.values())if(route().view==='activity'||(route().view==='job'?String(job.id)===route().id:String(job.collection_id)===route().id))pollJob(job.id);
  } catch(error) { state.collectionError=error.message; if(renderView||route().view==='collections') render(); }
  finally {state.collectionLoading=false;}
}
function collectionsView(){return heading('Collections','Organize sources and choose where to search.','<a class="btn primary" href="#new">Create collection</a>')+(state.collectionError?`<div class="error" role="alert">${esc(state.collectionError)} <button class="btn" data-action="refresh">Try again</button></div>`:'')+(!state.loaded?(state.collectionError?'':'<div class="surface empty" role="status">Loading collections…</div>'):!state.collections.length?'<div class="surface empty"><h2>Add your first collection</h2><p>Create a collection, then upload the sources you want to search.</p><a class="btn primary" href="#new">Create collection</a></div>':`<div class="surface">${state.collections.map(c=>`<article class="collection-row"><div><h2><a href="${link('collection',c.id)}">${esc(c.name)}</a></h2><p>${esc(c.published_documents??c.documents??0)} published documents · Elasticsearch${c.also_write_milvus?' + Milvus':''}</p></div><div class="actions">${badge(c.status)}<a class="btn" href="${link('collection',c.id)}">Open collection</a></div></article>`).join('')}</div>`);}
function newView(){return `<a class="back" href="#collections">Back to collections</a>${heading('Create collection','Give your sources a shared home.')}<form id="create-form" class="surface pad form-width"><div class="field"><label for="collection-name">Collection name</label><input id="collection-name" name="name" maxlength="120" required autocomplete="off" placeholder="e.g. Platform documentation"></div><p class="muted">Content is always written to Elasticsearch.</p><label class="check"><input type="checkbox" id="also-milvus"><span>Also write to Milvus<small>You can duplicate the collection to Milvus later.</small></span></label><div class="error" id="form-error" role="alert"></div><div class="form-footer"><a class="btn" href="#collections">Cancel</a><button class="btn primary" type="submit">Create collection</button></div></form>`;}
const sourcePending=new Set(), sourceLoading=new Set();
const sourceTerminal=state=>['published','unchanged','observed','failed','deferred','cancelled'].includes(state);
function scheduleFields(prefix,schedule={}){return `<label class="check"><input type="checkbox" id="${prefix}-enabled" ${schedule.enabled?'checked':''}><span>Enable daily checks<small>Optional. Each check starts within this local acquisition window. Start must precede end on the same day.</small></span></label><div class="field"><label for="${prefix}-timezone">IANA timezone</label><input id="${prefix}-timezone" value="${esc(schedule.timezone||'America/Chicago')}" required maxlength="100" placeholder="America/Chicago"></div><div class="field"><label for="${prefix}-start">Window starts</label><input id="${prefix}-start" type="time" value="${esc(schedule.start||'02:00')}" required></div><div class="field"><label for="${prefix}-end">Window ends</label><input id="${prefix}-end" type="time" value="${esc(schedule.end||'06:00')}" required></div>`;}
function readSchedule(prefix){return {enabled:$(prefix+'-enabled').checked,timezone:$(prefix+'-timezone').value.trim(),start:$(prefix+'-start').value,end:$(prefix+'-end').value};}
function sourceCounts(counts={}){if('pages' in counts||'assets' in counts)return `Pages retained: ${esc(counts.pages??0)} · Assets retained: ${esc(counts.assets??0)}`;return ['new','changed','unchanged','missing','failed'].map(key=>`${key}: ${esc(counts[key]??0)}`).join(' · ');}
function sourceDate(value,timezone){if(!value)return 'Not scheduled';const date=new Date(value);return Number.isNaN(date.getTime())?'Unavailable':new Intl.DateTimeFormat(undefined,{timeZone:timezone||'America/Chicago',year:'numeric',month:'numeric',day:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'}).format(date);}
function sourcesView(collectionId){const id=String(collectionId),sources=state.sources.get(id),uploads=state.sourceUploads.get(id)||[],oneTime=state.oneTimeSources.get(id)||[];return `<h2 class="section-title">Data sources</h2><p class="muted">Edit acquisition scope and check schedules here. Changes apply to future checks; retained source history stays intact.</p>${state.sourceErrors.has(id)?`<p class="error" role="alert">${esc(state.sourceErrors.get(id))}</p><button class="btn" data-source-action="refresh">Try again</button>`:''}${!sources?'<p class="muted">Loading data sources…</p>':!sources.length&&!uploads.length&&!oneTime.length?'<div class="surface pad"><p>No sources are registered yet.</p><div class="actions"><a class="btn" href="'+link('website',collectionId)+'">Add website</a><a class="btn" href="'+link('location',collectionId)+'">Connect location</a><a class="btn" href="'+link('upload',collectionId)+'">Add files</a></div></div>':sources.map(source=>{const sid=String(source.source_id),runs=state.sourceRuns.get(sid)||[],latest=runs[0],schedule=source.schedule||{},uri=source.kind==='location'?source.location?.uri:(source.seed_urls||[]).join(', ');return `<article class="surface pad source-entry"><div class="source-entry-heading"><div><h3>${esc(source.name)}</h3><p class="muted">${sourceKind(source)}</p></div><button class="btn" data-source-action="edit" data-source-id="${esc(sid)}">Edit source</button></div><p class="source-uri">${esc(uri)}</p><p class="muted">${schedule.enabled?`${source.paused?'Paused · ':''}Daily ${esc(schedule.start)}–${esc(schedule.end)} · ${esc(schedule.timezone)}`:'Automatic checks off'}${schedule.enabled?` · Next: ${esc(sourceDate(source.next_fire,schedule.timezone))}`:''}</p><p>Latest check: ${latest?badge(latest.state):'No checks yet'}${latest?` · ${sourceCounts(latest.counts)}`:''}</p>${state.sourceHistoryErrors.has(sid)?'<p class="error" role="alert">Run history could not be loaded. Source settings are still available.</p>':''}<div class="actions"><button class="btn" data-source-action="check" data-source-id="${esc(sid)}" ${latest&&!sourceTerminal(latest.state)?'disabled':''}>Check now</button>${schedule.enabled?`<button class="btn quiet" data-source-action="pause" data-source-id="${esc(sid)}">${source.paused?'Resume daily checks':'Pause daily checks'}</button>`:''}</div><details data-disclosure-key="website-runs:${esc(sid)}"><summary>Run history (${runs.length})</summary>${runs.length?runs.map(run=>`<p>${esc(sourceDate(run.nominal_fire,schedule.timezone))} · ${badge(run.state)} · ${sourceCounts(run.counts)}${run.job_id?` · <a href="${link('job',run.job_id)}">Ingestion progress</a>`:''}${run.error_code?` · ${esc(run.error_code)}`:''}</p>`).join(''):'<p class="muted">No runs recorded.</p>'}</details></article>`;}).join('')}${uploads.length?`<section class="surface pad source-entry"><h3>Uploaded files</h3><p class="muted">Uploads are checked on demand when you replace a file.</p><div class="table-scroll"><table><thead><tr><th>File</th><th>Status</th><th>Action</th></tr></thead><tbody>${uploads.map((file,i)=>`<tr><td>${esc(file.filename)}</td><td>${badge(file.status)}</td><td><button class="btn quiet" data-upload-replace="${i}">Replace file</button></td></tr>`).join('')}</tbody></table></div></section>`:''}${oneTime.length?`<section class="surface pad source-entry"><h3>One-time inputs</h3><p class="muted">These admitted inputs have no saved acquisition settings. Set up a source to edit its future checks.</p>${oneTime.map((input,i)=>`<div class="source-entry-heading"><p class="source-uri">${esc(input.uri)}</p><button class="btn quiet" data-register-source="${i}">Set up rechecks</button></div>`).join('')}</section>`:''}`;}
function attachSourceJob(collectionId,run){if(!run.job_id||state.ignoredJobs.has(String(run.job_id)))return;const id=String(run.job_id);if(!state.jobs.has(id)){state.jobs.set(id,{id,collection_id:String(collectionId),status:'queued',documents:[],operations:[]});saveJobs();pollJob(id);}}
async function refreshSources(collectionId){collectionId=String(collectionId);if(sourceLoading.has(collectionId))return;sourceLoading.add(collectionId);const paint=()=>{if(route().view==='collection'&&route().id===collectionId){const section=$('website-sources');if(section){const open=new Set(Array.from(section.querySelectorAll('details[open]'),el=>el.dataset.disclosureKey));section.innerHTML=sourcesView(collectionId);section.querySelectorAll('details').forEach(el=>el.open=open.has(el.dataset.disclosureKey));}}};try{const data=await api(path(collectionId)+'/sources');const sources=data.sources||[];state.sources.set(collectionId,sources);state.sourceUploads.set(collectionId,data.uploads||[]);state.oneTimeSources.set(collectionId,data.one_time_sources||[]);state.sourceErrors.delete(collectionId);sourcePending.delete(collectionId);paint();await Promise.allSettled(sources.map(async source=>{const id=String(source.source_id);try{const data=await api(path(collectionId)+'/sources/'+encodeURIComponent(id)+'/runs');const runs=data.runs||[];state.sourceRuns.set(id,runs);state.sourceHistoryErrors.delete(id);for(const run of runs)attachSourceJob(collectionId,run);if(runs.some(run=>!sourceTerminal(run.state)))sourcePending.add(collectionId);}catch{state.sourceHistoryErrors.add(id);}paint();}));}catch{state.sourceErrors.set(collectionId,'Data sources could not be loaded. Try again.');sourcePending.delete(collectionId);}finally{sourceLoading.delete(collectionId);paint();}}
function editSourceSchedule(source,collectionId){const dialog=$('dialog'),website=source.kind!=='location',policy=source.policy||{},locationSpec=source.location||{};const field=(label,id,value,extra='')=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" value="${esc(value??'')}" ${extra}></div>`;const area=(label,id,values)=>`<div class="field"><label for="${id}">${label}</label><textarea id="${id}" rows="2">${esc((values||[]).join('\n'))}</textarea></div>`;dialog.innerHTML=`<form id="source-schedule-form"><h2 id="dialog-title">Edit source</h2><p class="muted">${sourceKind(source)}</p>${field('Source name','edit-source-name',source.name,'required maxlength="120"')}${website?`${area('Starting URLs','edit-source-seeds',source.seed_urls)}${area('Allowed hosts','edit-source-hosts',policy.allowed_hosts)}${area('Page URL prefixes','edit-source-prefixes',policy.page_prefixes)}<div class="form-pair">${field('Crawl depth · blank for unlimited','edit-source-depth',policy.max_depth,'type="number" min="0" step="1"')}${field('Page limit · blank for unlimited','edit-source-pages',policy.max_pages,'type="number" min="1" step="1"')}</div><label class="check"><input type="checkbox" id="edit-source-images" ${policy.include_images?'checked':''}><span>Include webpage images</span></label><label class="check"><input type="checkbox" id="edit-source-https" ${policy.prefer_https?'checked':''}><span>Prefer HTTPS</span></label>${field('Included linked file extensions','edit-source-included',(policy.included_extensions||[]).join(', '))}${field('Ignored linked file extensions','edit-source-ignored',(policy.ignored_extensions||[]).join(', '))}`:`${field('Registered directory or document URL','edit-source-uri',locationSpec.uri,'required')}${area('Allowed hosts for a document URL','edit-source-location-hosts',locationSpec.allowed_hosts)}<details><summary>Directory options</summary><label class="check"><input type="checkbox" id="edit-source-recursive" ${locationSpec.recursive!==false?'checked':''}><span>Include subdirectories</span></label>${field('Directory depth','edit-source-directory-depth',locationSpec.max_depth??8,'type="number" min="0" max="32"')}${field('Files per check','edit-source-files',locationSpec.max_files??128,'type="number" min="1" max="512"')}</details>`}${sourceCaptionField('edit-source-captions',source.kind,source.captions_enabled,website&&!policy.include_images)}<h3 class="section-title">Recheck schedule</h3>${scheduleFields('edit-source',source.schedule)}<label class="check"><input type="checkbox" id="edit-source-paused" ${source.paused?'checked':''}><span>Pause automatic checks</span></label><p class="muted">Saving updates future checks. Existing captures and published content retain their provenance.</p><div class="error" id="source-schedule-error" role="alert"></div><div class="actions"><button type="button" class="btn" data-close>Cancel</button><button type="submit" class="btn primary">Save changes</button></div></form>`;dialog.querySelector('[data-close]').onclick=()=>dialog.close();if(website)$('edit-source-images').onchange=()=>{const captions=$('edit-source-captions');captions.disabled=!$('edit-source-images').checked;if(captions.disabled)captions.checked=false;};$('source-schedule-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,lines=id=>$(id).value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean),ext=id=>$(id).value.split(',').map(v=>v.trim().toLowerCase()).filter(Boolean);const body={expected_version:source.version,name:$('edit-source-name').value.trim(),schedule:readSchedule('edit-source'),paused:$('edit-source-paused').checked,captions_enabled:$('edit-source-captions').checked};if(website){body.seed_urls=lines('edit-source-seeds');body.policy={allowed_hosts:lines('edit-source-hosts'),page_prefixes:lines('edit-source-prefixes'),max_depth:$('edit-source-depth').value.trim()?Number($('edit-source-depth').value):null,max_pages:$('edit-source-pages').value.trim()?Number($('edit-source-pages').value):null,include_images:$('edit-source-images').checked,prefer_https:$('edit-source-https').checked,included_extensions:ext('edit-source-included'),ignored_extensions:ext('edit-source-ignored')};}else{const uri=$('edit-source-uri').value.trim();body.location={uri,...(/^https?:/.test(uri)?{allowed_hosts:lines('edit-source-location-hosts')}:{recursive:$('edit-source-recursive').checked,max_depth:Number($('edit-source-directory-depth').value),max_files:Number($('edit-source-files').value)})};}setBusy(form,true);try{await api(path(collectionId)+'/sources/'+encodeURIComponent(source.source_id),{method:'PATCH',body:JSON.stringify(body)});dialog.close();await refreshSources(collectionId);message('Source settings saved.');}catch(error){$('source-schedule-error').textContent=error.status===409?'This source changed. Cancel and reopen it to load the latest settings.':error.message;setBusy(form,false);if(website)$('edit-source-captions').disabled=!$('edit-source-images').checked;}};dialog.showModal();}
document.addEventListener('click',async event=>{const registerButton=event.target.closest('[data-register-source]');if(registerButton){const c=current(),input=(state.oneTimeSources.get(String(c?.id))||[])[Number(registerButton.dataset.registerSource)];if(c&&input){state.sourceDrafts.set(String(c.id),input);location.hash=link(input.source_kind==='html'?'website':'location',c.id);}return;}const uploadButton=event.target.closest('[data-upload-replace]');if(uploadButton){const c=current(),file=(state.sourceUploads.get(String(c?.id))||[])[Number(uploadButton.dataset.uploadReplace)];if(c&&file)replaceUploadedFile(file,c.id);return;}const button=event.target.closest('[data-source-action]');if(!button)return;const c=current();if(!c)return;const action=button.dataset.sourceAction,id=button.dataset.sourceId,source=(state.sources.get(String(c.id))||[]).find(source=>String(source.source_id)===id);if(action==='refresh'){refreshSources(c.id);return;}if(!source)return;if(action==='schedule'||action==='edit'){editSourceSchedule(source,c.id);return;}button.disabled=true;try{if(action==='check'){const result=await api(path(c.id)+'/sources/'+encodeURIComponent(id)+'/check',{method:'POST'});state.sourceRuns.set(id,[result.run,...(state.sourceRuns.get(id)||[]).filter(run=>run.run_id!==result.run.run_id)]);sourcePending.add(String(c.id));attachSourceJob(c.id,result.run);message('Source check queued.');}else if(action==='pause'){await api(path(c.id)+'/sources/'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify({expected_version:source.version,paused:!source.paused})});message(source.paused?'Daily checks resumed.':'Daily checks paused.');}await refreshSources(c.id);}catch{message('Source action could not be completed. Refresh its history before trying again.',true);button.disabled=false;}});
function imageOriginsView(c){const origins=c.image_origins||{};const rows=[['webpage','Webpage images'],['pdf','PDF image regions'],['other','Other document images']].filter(([key])=>key!=='other'||origins.other?.associations);return `<section class="surface pad collection-section"><h2>Images by origin</h2><p class="muted">Images selected for captioning from current sources. Unique images count identical image content once per origin; associations retain each source and region.</p><div class="table-scroll"><table><thead><tr><th>Origin</th><th>Unique images</th><th>Associations</th><th>Pending</th><th>Published captions</th>${c.caption_failed?'<th>Errors</th>':''}</tr></thead><tbody>${rows.map(([key,label])=>{const r=origins[key]||{};return `<tr><td>${label}</td><td>${esc(r.unique_images??0)}</td><td>${esc(r.associations??0)}</td><td>${esc(r.pending??0)}</td><td>${esc(r.completed??0)}</td>${c.caption_failed?`<td>${esc(r.failed??0)}</td>`:''}</tr>`;}).join('')}</tbody></table></div></section>`;}
function processingView(c){const p=c.processing||{};if(!p.sources_pending&&!p.captions_pending&&!p.publication_pending&&!p.sources_failed&&!c.caption_failed)return '';return `<section class="surface pad collection-section"><h2>Background processing</h2><p class="muted">Published content remains searchable while new sources and image captions are processed.</p><dl class="processing-summary">${p.sources_pending?`<div><dt>Sources pending</dt><dd>${esc(p.sources_pending)}</dd></div>`:''}${p.admission_waiting?`<div><dt>Extraction complete · awaiting admission</dt><dd>${esc(p.admission_waiting)}</dd></div>`:''}${p.captions_pending?`<div><dt>Caption tasks pending</dt><dd>${esc(p.captions_pending)}</dd></div>`:''}${p.publication_pending?'<div><dt>Collection write</dt><dd>Pending publication</dd></div>':''}${p.sources_failed?`<div><dt>Current source errors</dt><dd>${esc(p.sources_failed)}</dd></div>`:''}${c.caption_failed?`<div><dt>Current caption errors</dt><dd>${esc(c.caption_failed)}</dd></div>`:''}</dl></section>`;}
function sourceKind(source){return source.kind==='location'?(/^https?:/.test(source.location?.uri||'')?'Document URL':'Registered directory'):'Website';}
function replaceUploadedFile(upload,collectionId){const dialog=$('dialog');dialog.innerHTML=`<form id="replace-file-form"><h2 id="dialog-title">Replace file</h2><p>${esc(upload.filename)}</p><p class="muted">The replacement keeps this source identity and creates a new retained revision.</p><div class="field"><label for="replacement-file">Replacement file</label><input id="replacement-file" type="file" required accept=".${esc(upload.filename.split('.').pop())}"></div>${/\.pdf$/i.test(upload.filename)?'<label class="check"><input id="replacement-captions" type="checkbox"><span>Generate image captions</span></label>':''}<div class="error" id="replacement-error" role="alert"></div><div class="actions"><button type="button" class="btn" data-close>Cancel</button><button type="submit" class="btn primary">Replace file</button></div></form>`;dialog.querySelector('[data-close]').onclick=()=>dialog.close();$('replace-file-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,file=$('replacement-file').files[0];if(!file)return;const data=new FormData();data.append('files',file,upload.filename);data.append('captions_enabled',String(Boolean($('replacement-captions')?.checked)));setBusy(form,true);try{const result=await api(path(collectionId)+'/ingestions',{method:'POST',body:data});state.jobs.set(result.job_id,{id:result.job_id,collection_id:String(collectionId),status:'queued',documents:[{name:upload.filename,status:'queued'}],operations:[]});saveJobs();dialog.close();message('Replacement uploaded. The published revision remains searchable until the update is ready.');pollJob(result.job_id);refreshSources(collectionId);}catch(error){$('replacement-error').textContent=error.message;setBusy(form,false);}};dialog.showModal();}
function collectionView(){const c=current(); if(!c)return unavailable(); const jobs=[...state.jobs.values()].filter(j=>j.collection_id===String(c.id)&&j.relevant!==false);return `<a class="back" href="#collections">Back to collections</a>${heading(c.name,'Manage the sources available to search.',`<a href="${link('search',c.id)}" class="btn quiet">Search collection</a><a href="${link('location',c.id)}" class="btn">Connect location</a><a href="${link('website',c.id)}" class="btn">Add website</a><a href="${link('upload',c.id)}" class="btn primary">Add files</a><details class="menu"><summary>Collection actions</summary><nav aria-label="Collection actions"><button data-action="delete">Delete collection</button></nav></details>`)}<div class="index-strip"><span>Elasticsearch ${badge(c.elasticsearch_status||c.status)}</span><span>Milvus: ${c.also_write_milvus?'enabled':'not enabled'}</span>${!c.also_write_milvus?'<button class="btn quiet" data-action="milvus">Duplicate to Milvus</button>':''}</div><div class="surface pad"><h2>Collection content</h2><p class="muted">${esc(c.published_documents??c.documents??0)} published documents${c.caption_pending?` · ${esc(c.caption_pending)} image captions pending`:''}${c.caption_failed?` · ${esc(c.caption_failed)} image captions failed`:''}</p>${c.documents?'<p class="muted">Search this collection to inspect matching source excerpts.</p>':'<p class="muted">Upload files to make this collection searchable.</p>'}<details class="audit" data-disclosure-key="collection-audit:${esc(c.id)}"><summary>Collection details</summary><pre>${esc(JSON.stringify({id:c.id,generation:c.generation,status:c.status,also_write_milvus:c.also_write_milvus},null,2))}</pre></details></div>${processingView(c)}${imageOriginsView(c)}<section id="website-sources">${sourcesView(c.id)}</section><h2 class="section-title">Ingestion activity</h2>${jobs.length?jobs.map(jobView).join(''):'<p class="muted">New uploads and their progress will appear here. Job links remain available after a page refresh.</p>'}`;}
function uploadView(){const c=current();if(!c)return unavailable();return `<a class="back" href="${link('collection',c.id)}">Back to ${esc(c.name)}</a>${heading('Add content',c.name)}<form id="upload-form" class="surface pad form-width"><div class="upload" id="dropzone"><h2>Upload files</h2><p>Choose PDF, DOCX, PPTX, CSV, XLS, XLSX, Markdown or plain text documents.</p><label for="files" class="sr-only">Choose files</label><input id="files" type="file" accept=".pdf,.docx,.pptx,.csv,.xls,.xlsx,.md,.markdown,.txt" multiple required><ul id="file-list" class="file-list"></ul></div><label class="check" style="margin-top:24px"><input id="captions" type="checkbox" disabled><span>Generate image captions for PDFs<small>Available only when all selected files are PDFs. Captions run asynchronously and may finish after text becomes searchable.</small></span></label><p class="muted">Writes to Elasticsearch${c.also_write_milvus?' and Milvus':''}.</p><div class="error" id="form-error" role="alert"></div><div class="form-footer"><a class="btn" href="${link('collection',c.id)}">Cancel</a><button class="btn primary" type="submit">Upload and process</button></div></form>`;}
function websiteView(){const c=current();if(!c)return unavailable();const draft=state.sourceDrafts.get(String(c.id));return `<a class="back" href="${link('collection',c.id)}">Back to ${esc(c.name)}</a>${heading('Add website',c.name)}<form id="website-form" class="surface pad form-width"><p>Retain whole HTML pages and selected linked assets. Native nv-ingest classifies and extracts image evidence into its parent page, keeping one searchable page record. Linked documents become separate sources. Save this website for manual checks or enable a daily acquisition window.</p><div class="field"><label for="website-name">Website name (optional)</label><input id="website-name" maxlength="120" value="${esc(draft?.filename||'')}" placeholder="e.g. Platform documentation"></div>${scheduleFields('new-source')}<div class="field"><label for="seed-urls">Starting page URLs</label><textarea id="seed-urls" rows="3" required placeholder="https://docs.example.com/guide/" aria-describedby="seed-help">${esc(draft?.uri||'')}</textarea><small id="seed-help">One URL per line, up to 5. Use HTTP or HTTPS destinations permitted by the server acquisition policy.</small></div><div class="field"><label for="allowed-hosts">Exact allowed hostnames</label><textarea id="allowed-hosts" rows="2" required placeholder="docs.example.com" aria-describedby="host-help">${esc(draft?.uri?new URL(draft.uri).hostname:'')}</textarea><small id="host-help">One hostname per line, up to 10. Review this scope before capture. Subdomains require their own entry.</small></div><div class="field"><label for="crawl-depth">Link depth</label><input id="crawl-depth" type="number" min="0" value="${draft?0:1}" placeholder="Unlimited"><small>0 captures starting pages only. Leave blank for unlimited depth within the allowed sections.</small></div><div class="field"><label for="crawl-pages">Page budget (optional)</label><input id="crawl-pages" type="number" min="1" placeholder="All pages within scope and depth"><small>Leave blank for complete scoped coverage. A budget stop is reported as incomplete.</small></div><div class="field"><label for="page-prefixes">HTML section prefixes</label><textarea id="page-prefixes" rows="2" placeholder="https://example.com/section/">${esc(draft?.uri||'')}</textarea><small>One full URL prefix per line. Linked assets can be outside these paths on allowed hosts.</small></div><div class="field"><label for="included-extensions">Linked file types to process</label><input id="included-extensions" value=".pdf,.docx,.pptx,.csv,.xls,.xlsx,.md,.txt" aria-describedby="extension-help"><small id="extension-help">Comma-separated extensions: PDF, DOCX, PPTX, CSV, XLS, XLSX, MD, MARKDOWN and TXT. Selected files are downloaded, retained and processed.</small></div><div class="field"><label for="ignored-extensions">Linked file types to ignore</label><input id="ignored-extensions" value=".gif,.avif" placeholder="e.g. .csv,.xlsx"><small>Ignored file and image types take precedence. GIF and AVIF are excluded by default.</small></div><label class="check"><input id="discover-images" type="checkbox"><span>Process webpage images<small>Download and retain PNG, JPEG, WebP, TIFF, BMP and safely normalized SVG images for native classification, OCR and structured evidence. GIF and AVIF are unsupported. Image evidence enriches the parent page; it does not add image vectors.</small></span></label>${sourceCaptionField('website-captions','website')}<p class="muted">Webpages are admitted independently; selected images and linked files are queued for separate asynchronous processing. Writes to Elasticsearch${c.also_write_milvus?' and Milvus':''} after processing and publication.</p><p id="web-capture-status" role="status" aria-live="polite"></p><div class="error" id="form-error" role="alert"></div><div class="form-footer"><a class="btn" href="${link('collection',c.id)}">Cancel</a><button class="btn primary" type="submit">Save and check website</button></div></form>`;}
function sourceCaptionField(id,kind,checked=false,disabled=false){return `<label class="check"><input id="${id}" type="checkbox" ${checked?'checked':''} ${disabled?'disabled':''}><span>${kind==='location'?'Caption eligible PDF images':'Caption webpage images'}<small>${kind==='location'?'PDF captions are optional. Office visuals are extracted automatically as grounded evidence.':'Applies to selected webpage images. Enable Process webpage images when adding the website.'} Captions run asynchronously and may finish after text becomes searchable.</small></span></label>`;}
function locationView(){const c=current();if(!c)return unavailable();const draft=state.sourceDrafts.get(String(c.id));return `<a class="back" href="${link('collection',c.id)}">Back to ${esc(c.name)}</a>${heading('Connect location',c.name)}<form id="location-form" class="surface pad form-width"><p>Connect a registered server directory or one supported document at an HTTP or HTTPS URL. Checks retain complete document bytes before processing. Supported formats: PDF, DOCX, PPTX, CSV, XLS, XLSX, Markdown and plain text.</p><div class="field"><label for="location-name">Source name</label><input id="location-name" maxlength="120" required value="${esc(draft?.filename||'')}" placeholder="e.g. Reference documents"></div><div class="field"><label for="location-roots">Registered server directories</label><select id="location-roots" aria-describedby="location-roots-help"><option value="">Loading registered directories…</option></select><small id="location-roots-help">Choose an approved directory alias, then add an optional relative subpath to its location URI. Server filesystem paths are not accepted.</small></div><div class="field"><label for="location-uri">Location URI</label><input id="location-uri" required value="${esc(draft?.uri||'')}" placeholder="location://alias/subdirectory" aria-describedby="location-uri-help"><small id="location-uri-help">Use a registered location:// URI or a direct HTTP(S) document URL. Cloud storage connectors and file:// paths are not supported.</small></div><div id="location-directory-options"><label class="check"><input id="location-recursive" type="checkbox" checked><span>Include subdirectories<small>Any excluded subtree or exhausted bound leaves the inventory incomplete and prevents ingestion.</small></span></label><div class="field"><label for="location-depth">Maximum directory depth</label><input id="location-depth" type="number" min="0" max="16" value="8" required></div></div><div class="field"><label for="location-files">Maximum files</label><input id="location-files" type="number" min="1" max="1000" value="128" required><small>The server also enforces per-file and total byte limits.</small></div><div class="field" id="location-http-options" hidden><label for="location-hosts">Exact allowed HTTP hostnames</label><textarea id="location-hosts" rows="2" placeholder="documents.example.com"></textarea><small>One hostname per line. Leave blank to use the document URL’s hostname. Redirect hosts must be explicitly included and permitted by the server.</small></div>${sourceCaptionField('location-captions','location')}${scheduleFields('location-source')}<p id="location-capture-status" role="status" aria-live="polite"></p><div class="error" id="form-error" role="alert"></div><div class="form-footer"><a class="btn" href="${link('collection',c.id)}">Cancel</a><button class="btn primary" type="submit">Save and check location</button></div></form>`;}
async function loadLocationRoots(form){try{const data=await api('/api/location-roots');if($('location-form')!==form)return;const select=$('location-roots');if(!select)return;const roots=(data.roots||[]).filter(root=>typeof root.alias==='string'&&typeof root.uri==='string'&&root.uri.startsWith('location://'));select.innerHTML=`<option value="">${roots.length?'Choose a registered directory':'No registered server directories'}</option>`+roots.map(root=>`<option value="${esc(root.uri)}">${esc(root.alias)}</option>`).join('');}catch{if($('location-form')!==form)return;const select=$('location-roots');if(select)select.innerHTML='<option value="">Registered directories unavailable</option>';const help=$('location-roots-help');if(help)help.textContent='Registered directories could not be loaded. A permitted HTTP(S) document URL can still be connected.';}}
function jobView(job){ const captions=job.captions||{}; const images=job.images||captions.images||[];const assets=job.assets||[];return `<section class="surface pad job" data-job="${esc(job.id)}"><div class="job-header"><div><h2>Ingestion progress</h2><p>${esc(job.stage||'Waiting for worker')}</p></div>${badge(job.status)}</div>${job.pollError?`<p class="error" role="alert">${esc(job.pollError)} Progress will retry automatically.</p>`:''}<div class="table-scroll"><table><caption class="sr-only">Uploaded files</caption><thead><tr><th>File</th><th>Status</th><th>Records</th></tr></thead><tbody>${(job.documents||[]).map(d=>`<tr><td>${esc(d.name)}</td><td>${badge(d.status)}</td><td>${esc(d.records??'—')}</td></tr>`).join('')}</tbody></table></div>${assets.length?`<div class="table-scroll"><table><caption>Linked assets</caption><thead><tr><th>Source</th><th>Kind</th><th>Native processing status</th></tr></thead><tbody>${assets.map(a=>`<tr><td>${esc(a.url||a.id)}</td><td>${esc(a.kind)}</td><td>${badge(a.status)}</td></tr>`).join('')}</tbody></table></div>`:''}${job.captions?`<p class="job-message">Image captions: ${esc(captions.pending??0)} pending · ${esc(captions.completed??0)} completed · ${esc(captions.failed??0)} failed</p>`:''}${images.length?`<div class="table-scroll"><table><caption class="sr-only">Individual image caption status</caption><thead><tr><th>Image</th><th>Caption status</th></tr></thead><tbody>${images.map(i=>`<tr><td>${esc(i.name||i.id||i.image_id)}</td><td>${badge(i.status)}${i.error?`<p class="error">${esc(i.error)}</p>`:''}</td></tr>`).join('')}</tbody></table></div>`:''}${(job.errors||[]).length?`<ul class="error">${job.errors.map(e=>`<li>${esc(typeof e==='string'?e:JSON.stringify(e))}</li>`).join('')}</ul>`:''}<details class="audit" data-disclosure-key="job-receipts:${esc(job.id)}"><summary>Operation receipts</summary><p class="muted">Job <a href="${link('job',job.id)}">${esc(job.id)}</a></p><pre>${esc(JSON.stringify(job.operations||[],null,2))}</pre></details></section>`;}
function searchView(){return heading('Search','Find answers in the collections you choose.')+`<div class="search-layout"><form id="search-form"><fieldset class="mode" ${state.searching?'disabled':''}><legend>Research mode</legend><label><input type="radio" name="mode" value="search" ${state.mode==='search'?'checked':''}>Search</label><label><input type="radio" name="mode" value="deep_research" ${state.mode==='deep_research'?'checked':''}>Deep research</label></fieldset><p id="mode-help" class="muted">${state.mode==='deep_research'?'Deep research plans additional bounded searches within the selected local collections.':'Search uses the selected collections. With none selected, answers use the model without collection retrieval.'}</p><div class="field"><label for="query">Your question</label><textarea id="query" ${state.searching?'disabled':''} required placeholder="Ask about your sources…">${esc(state.query)}</textarea></div><p class="scope" id="scope"></p><div class="error" id="search-error" role="alert">${esc(state.searchError)}</div><button class="btn primary" type="submit" ${state.searching?'disabled':''}>${state.searching?'Searching…':state.mode==='deep_research'?'Start deep research':'Search'}</button>${state.searching?'<button class="btn" type="button" id="cancel-search">Stop</button>':''}<p id="search-progress" class="muted" role="status">${esc(state.searchStage)}</p><div id="results">${resultsView()}</div></form><aside class="search-options"><fieldset ${state.searching?'disabled':''}><legend>Collections</legend>${state.loaded?(state.collections.length?state.collections.map(c=>`<label class="check"><input type="checkbox" name="collection" value="${esc(c.id)}" ${state.selected.has(String(c.id))?'checked':''}><span>${esc(c.name)}${c.also_write_milvus?'':'<small>Elasticsearch only</small>'}</span></label>`).join(''):'<p class="muted">No collections yet. <a href="#new">Create one</a> to add sources.</p>'):'<p class="muted">Loading collections…</p>'}</fieldset><button type="button" class="btn quiet" data-action="no-collections" ${state.searching?'disabled':''}>Use no collections</button><div class="field"><label for="backend">Search index</label><select id="backend" ${state.searching?'disabled':''}><option value="elasticsearch" ${state.backend==='elasticsearch'?'selected':''}>Elasticsearch</option><option value="milvus" ${state.backend==='milvus'?'selected':''}>Milvus</option></select></div><p class="muted" id="index-help"></p></aside></div>`;}
function safeUri(uri){if(typeof uri!=='string'||!/^https?:\/\//i.test(uri))return null;try {const u=new URL(uri);return ['https:','http:'].includes(u.protocol)?u.href:null;}catch{return null;}}
function resultsView(){const r=state.result;if(!r)return '';return `<section class="answer" aria-busy="${state.searching}"><h2>${state.searching?'Answer · generating':'Answer'}</h2><div class="answer-text">${esc(r.answer||'')}</div>${(r.warnings||[]).length?`<ul class="warnings">${r.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`:''}${!state.searching?`<h2 class="section-title">Sources</h2>${(r.sources||[]).length?`<ol class="source-links">${r.sources.map((source,i)=>{const uri=safeUri(source.uri),label=esc(source.title&&!/^[a-f0-9]{32,64}(?:\.[a-z0-9]+)?$/i.test(source.title)?source.title:uri||'Source '+(i+1))+(source.page!=null?` · Page ${esc(source.page)}`:'');return `<li><span class="muted">[${esc(source.citation_id||'S'+(i+1))}]</span> ${uri?`<a href="${esc(uri)}" target="_blank" rel="noopener noreferrer">${label}</a>`:label}</li>`;}).join('')}</ol>`:'<p class="muted">No collection sources used.</p>'}`:''}</section>`;}
function updateSearchProgress(){if(route().view!=='search')return;const node=$('results');if(node)node.innerHTML=resultsView();const progress=$('search-progress');if(progress)progress.textContent=state.searchStage;}
async function runSearch(){
 state.searching=true;state.result=null;state.searchStage=state.mode==='deep_research'?'Planning local research…':'Retrieving sources…';state.searchAbort=new AbortController();render();
 const body={query:state.query,collection_ids:[...state.selected],backend:state.backend,mode:state.mode};
 try{state.result=await streamSearch(body,(kind,data)=>{if(kind==='status'){state.searchStage=data.stage==='generating'?'Generating answer…':data.stage==='planning'?'Planning local research…':'Retrieving sources…';}else if(kind==='delta'){if(!state.result)state.result={answer:'',sources:[],warnings:[]};state.result.answer+=data.text;}else if(kind==='complete'){state.result=data;state.searchStage='Answer ready.';}updateSearchProgress();},state.searchAbort.signal);}
 catch(error){state.result=null;state.searchStage='';state.searchError=error.name==='AbortError'?'Search stopped.':error.message;}
 finally{state.searching=false;state.searchAbort=null;if(route().view==='search')render();}
}
function updateScope(){if(!$('scope'))return;const selected=state.collections.filter(c=>state.selected.has(String(c.id)));$('scope').textContent=selected.length?'Selected collections: '+selected.map(c=>c.name).join(', '):'No collections selected. '+(state.mode==='deep_research'?'No local retrieval runs without selected collections.':'Answer without collection retrieval.');$('index-help').textContent=state.backend==='milvus'?'Only collections duplicated to Milvus can be searched with this index.':'All collections are written to Elasticsearch.';}
function render(){
 const r=route(), view=$('view'), scope=JSON.stringify([r.view,r.id]);
 // Only audit disclosures in the same view survive background replacement.
 // Menus and a different collection/job deliberately begin from closed markup.
 const openDisclosures=new Set(view.dataset.renderScope===scope
   ? Array.from(view.querySelectorAll('details[data-disclosure-key][open]'),d=>d.dataset.disclosureKey)
   : []);
 document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(r.view==='admin'?'admin':r.view==='search'?'search':'collections')));let html; if(r.view==='admin')html=adminView();else if(r.view==='new')html=newView();else if(r.view==='upload')html=uploadView();else if(r.view==='website')html=websiteView();else if(r.view==='location')html=locationView();else if(r.view==='collection')html=collectionView();else if(r.view==='search')html=searchView();else if(r.view==='job'){const job=state.jobs.get(r.id);html=heading('Ingestion progress','Follow document indexing, linked asset processing and optional PDF image captions.')+(job?jobView(job):'<p class="muted">Loading job…</p>');if(!job)pollJob(r.id);}else html=collectionsView();view.innerHTML=html;view.dataset.renderScope=scope;
 view.querySelectorAll('details[data-disclosure-key]').forEach(d=>{d.open=openDisclosures.has(d.dataset.disclosureKey);});
 document.title=(r.view==='admin'?'Admin':r.view==='search'?'Search':current()?.name||'Collections')+' · Agentic RAG';bind();updateScope();}
function setBusy(form,busy){for(const el of form.querySelectorAll('button,input,textarea,select'))el.disabled=busy;form.setAttribute('aria-busy',String(busy));}
function bind(){
 if(route().view==='admin')bindAdmin();
 $('create-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;const name=$('collection-name').value.trim();if(!name){$('form-error').textContent='Enter a collection name.';return;}const body={name,also_write_milvus:$('also-milvus').checked};setBusy(form,true);try {const c=await api('/api/collections',{method:'POST',body:JSON.stringify(body)});await refreshCollections();message('Collection created.');location.hash=link('collection',c.id||c.collection?.id);}catch(error){$('form-error').textContent=error.message;setBusy(form,false);}});
 const upload=$('upload-form');if(upload){let files=[];const showFiles=()=>{const onlyPDF=files.length>0&&files.every(f=>/\.pdf$/i.test(f.name));$('captions').disabled=!onlyPDF;if(!onlyPDF)$('captions').checked=false;$('file-list').innerHTML=files.map(f=>`<li><span>${esc(f.name)}</span><small>${(f.size/1024).toFixed(1)} KB</small></li>`).join('');};$('files').addEventListener('change',e=>{files=[...e.target.files];showFiles();});$('dropzone').addEventListener('dragover',e=>e.preventDefault());$('dropzone').addEventListener('drop',e=>{e.preventDefault();files=[...e.dataTransfer.files];if(files.length){$('files').required=false;showFiles();}});upload.addEventListener('submit',async e=>{e.preventDefault();if(!files.length){$('form-error').textContent='Choose at least one file.';return;}const c=current();const data=new FormData();files.forEach(f=>data.append('files',f));data.append('captions_enabled',String(files.every(f=>/\.pdf$/i.test(f.name))&&$('captions').checked));setBusy(upload,true);try {const result=await api(path(c.id)+'/ingestions',{method:'POST',body:data});if(!result.job_id)throw Error('The upload response did not include a job ID. Check collection activity before uploading again.');state.jobs.set(result.job_id,{id:result.job_id,collection_id:String(c.id),status:'queued',documents:files.map(f=>({name:f.name,status:'queued'})),captions:{pending:0,completed:0,failed:0},operations:[]});saveJobs();location.hash=link('collection',c.id);message('Files uploaded. Processing progress appears below.');pollJob(result.job_id);}catch(error){$('form-error').textContent=error.message;setBusy(upload,false);showFiles();}});}
 const locationForm=$('location-form');if(locationForm){
  loadLocationRoots(locationForm);
  const uriInput=$('location-uri'),rootSelect=$('location-roots');
  const updateMode=()=>{const http=/^https?:\/\//i.test(uriInput.value.trim());if($('location-directory-options'))$('location-directory-options').hidden=http;if($('location-http-options'))$('location-http-options').hidden=!http;};
  uriInput.addEventListener('input',updateMode);rootSelect?.addEventListener('change',()=>{if(rootSelect.value){uriInput.value=rootSelect.value;updateMode();}});updateMode();
  locationForm.addEventListener('submit',async event=>{event.preventDefault();const c=current(),uri=uriInput.value.trim(),http=/^https?:\/\//i.test(uri);const error=$('form-error');error.textContent='';if(!/^(location|https?):\/\//i.test(uri)){error.textContent='Enter a registered location:// URI or a direct HTTP(S) document URL.';return;}const body={name:$('location-name').value.trim(),uri,recursive:$('location-recursive').checked,max_depth:Number($('location-depth').value),max_files:Number($('location-files').value),allowed_hosts:http?$('location-hosts').value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean):[],captions_enabled:$('location-captions').checked,schedule:readSchedule('location-source')};
   $('location-capture-status').textContent='Saving location and requesting its first check…';setBusy(locationForm,true);
   try{const result=await api(path(c.id)+'/location-sources',{method:'POST',body:JSON.stringify(body)});if(!result.source?.source_id||!result.run?.run_id)throw Error('Location response was incomplete. Check saved sources before retrying.');state.sourceRuns.set(String(result.source.source_id),[result.run]);if(!sourceTerminal(result.run.state))sourcePending.add(String(c.id));attachSourceJob(c.id,result.run);location.hash=link('collection',c.id);state.sourceDrafts.delete(String(c.id));message('Location saved. Its first check is queued.');refreshSources(c.id);}
   catch(error){$('location-capture-status').textContent='';$('form-error').textContent=error.message;setBusy(locationForm,false);}
  });
 }
 const website=$('website-form');if(website){
  const lines=value=>value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);
  const extensions=value=>value.split(',').map(v=>v.trim().toLowerCase()).filter(Boolean);
  const updateCaptionChoice=()=>{const captions=$('website-captions');captions.disabled=!$('discover-images').checked;if(captions.disabled)captions.checked=false;};$('discover-images').addEventListener('change',updateCaptionChoice);updateCaptionChoice();
  const fillHosts=()=>{if($('allowed-hosts').value.trim())return;const hosts=[];for(const value of lines($('seed-urls').value)){try{hosts.push(new URL(value).hostname);}catch{}}$('allowed-hosts').value=[...new Set(hosts)].join('\n');};
  $('seed-urls').addEventListener('change',fillHosts);$('seed-urls').addEventListener('blur',fillHosts);
  website.addEventListener('submit',async e=>{e.preventDefault();const c=current();const body={name:$('website-name').value.trim()||undefined,schedule:readSchedule('new-source'),seed_urls:lines($('seed-urls').value),allowed_hosts:lines($('allowed-hosts').value),page_prefixes:lines($('page-prefixes').value),max_depth:$('crawl-depth').value.trim()?Number($('crawl-depth').value):null,max_pages:$('crawl-pages').value.trim()?Number($('crawl-pages').value):null,include_images:$('discover-images').checked,captions_enabled:$('website-captions').checked,included_extensions:extensions($('included-extensions').value),ignored_extensions:extensions($('ignored-extensions').value)};
   $('form-error').textContent='';$('web-capture-status').textContent='Saving website and requesting its first check…';setBusy(website,true);
   try{const result=await api(path(c.id)+'/web-sources',{method:'POST',body:JSON.stringify(body)});if(!result.source?.source_id||!result.run?.run_id)throw Error('Website response was incomplete. Check saved sources before retrying.');state.sourceRuns.set(String(result.source.source_id),[result.run]);sourcePending.add(String(c.id));attachSourceJob(c.id,result.run);location.hash=link('collection',c.id);state.sourceDrafts.delete(String(c.id));message('Website saved. Its first check is queued.');refreshSources(c.id);}
   catch(error){$('web-capture-status').textContent='';$('form-error').textContent=error.message;setBusy(website,false);updateCaptionChoice();}
  });
 }
 $('search-form')?.addEventListener('submit',async e=>{e.preventDefault();if(state.searching)return;state.query=$('query').value.trim();state.searchError='';if(!state.query){state.searchError='Enter a question.';}else if(state.backend==='milvus'&&state.collections.some(c=>state.selected.has(String(c.id))&&!c.also_write_milvus)){state.searchError='Duplicate each selected collection to Milvus, or choose Elasticsearch.';}if(state.searchError){$('search-error').textContent=state.searchError;return;}await runSearch();});
 $('cancel-search')?.addEventListener('click',()=>state.searchAbort?.abort());
 $('query')?.addEventListener('input',e=>state.query=e.target.value);
 document.querySelectorAll('input[name=collection]').forEach(el=>el.addEventListener('change',()=>{el.checked?state.selected.add(el.value):state.selected.delete(el.value);updateScope();}));
 document.querySelectorAll('input[name=mode]').forEach(el=>el.addEventListener('change',()=>{state.mode=el.value;render();}));$('backend')?.addEventListener('change',e=>{state.backend=e.target.value;updateScope();});
}
function saveJobs(){try{sessionStorage.setItem('agentic-rag-job-links',JSON.stringify([...state.jobs.values()].map(j=>({id:j.id,collection_id:j.collection_id}))));}catch{}}
const polling=new Set();
function retireJob(id,collectionId){id=String(id);const before=state.jobs.get(id);collectionId=collectionId||before?.collection_id;state.ignoredJobs.add(id);state.jobs.delete(id);saveJobs();if(route().view==='job'&&route().id===id)location.hash=state.collections.some(c=>String(c.id)===String(collectionId))?link('collection',collectionId):link('collections');}
async function pollJob(id){id=String(id);if(polling.has(id)||state.ignoredJobs.has(id))return;polling.add(id);try {const data=await api('/api/jobs/'+encodeURIComponent(id));const before=state.jobs.get(id)||{};if(data.relevant===false||state.ignoredJobs.has(id)||state.removedCollections.has(String(data.collection_id||before.collection_id))){retireJob(id,data.collection_id||before.collection_id);if(['collection','job','activity'].includes(route().view))render();return;}const job={...before,...data,id,pollError:''};state.jobs.set(id,job);saveJobs();if(['collection','job'].includes(route().view))render();if(!terminal(job.status)||Number(job.captions?.pending)>0)setTimeout(()=>pollJob(id),2000);}catch(error){if(error.status===404||error.status===410||state.ignoredJobs.has(id)){retireJob(id);if(['collection','job','activity'].includes(route().view))render();return;}const before=state.jobs.get(id)||{id};state.jobs.set(id,{...before,pollError:error.message});if(['collection','job'].includes(route().view))render();setTimeout(()=>pollJob(id),5000);}finally{polling.delete(id);}}
function confirmDelete(){const c=current();if(!c)return;const dialog=$('dialog');dialog.innerHTML=`<form id="delete-form"><h2 id="dialog-title">Delete collection</h2><p>Remove <strong>${esc(c.name)}</strong> from search and request deletion of its Elasticsearch${c.also_write_milvus?' and Milvus':''} index.</p><div class="field"><label for="confirm-name">Type the collection name to confirm</label><input id="confirm-name" required autocomplete="off"></div><div class="error" id="delete-error" role="alert"></div><div class="actions"><button class="btn" type="button" data-close>Cancel</button><button class="btn danger" type="submit">Delete collection</button></div></form>`;dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();if($('confirm-name').value!==c.name){$('delete-error').textContent='Enter the exact collection name.';return;}setBusy(e.currentTarget,true);try{await api(path(c.id),{method:'DELETE'});state.removedCollections.add(String(c.id));state.collections=state.collections.filter(item=>String(item.id)!==String(c.id));state.selected.delete(String(c.id));for(const [id,job] of state.jobs)if(String(job.collection_id)===String(c.id))retireJob(id);dialog.close();await refreshCollections();location.hash='collections';message('Collection deletion requested.');}catch(error){$('delete-error').textContent=error.message;setBusy($('delete-form'),false);}};dialog.showModal();}
function confirmMilvus(){const c=current();const dialog=$('dialog');dialog.innerHTML=`<h2 id="dialog-title">Duplicate to Milvus</h2><p>Copy the current content in <strong>${esc(c.name)}</strong> to Milvus and also write future uploads to Milvus.</p><p class="muted">Elasticsearch remains the default search index.</p><div class="error" id="milvus-error" role="alert"></div><div class="actions"><button class="btn" data-close>Cancel</button><button class="btn primary" id="confirm-milvus">Duplicate to Milvus</button></div>`;dialog.querySelector('[data-close]').onclick=()=>dialog.close();$('confirm-milvus').onclick=async()=>{const b=$('confirm-milvus');b.disabled=true;try{const result=await api(path(c.id)+'/milvus',{method:'POST',body:JSON.stringify({enabled:true})});dialog.close();await refreshCollections({renderView:true});message('Milvus duplication requested.');if(result.job_id){state.jobs.set(result.job_id,{id:result.job_id,collection_id:String(c.id),status:'queued'});saveJobs();pollJob(result.job_id);}}catch(error){$('milvus-error').textContent=error.message;b.disabled=false;}};dialog.showModal();}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('main').focus();return;}const action=e.target.closest('[data-action]')?.dataset.action;if(action==='no-collections'){state.selected.clear();render();}if(action==='refresh')refreshCollections({renderView:true});if(action==='delete')confirmDelete();if(action==='milvus')confirmMilvus();document.querySelectorAll('.menu[open]').forEach(menu=>{if(!menu.contains(e.target)||action)menu.open=false;});});
window.addEventListener('hashchange',()=>{if(state.searching)state.searchAbort?.abort();message();const r=route();if(r.view==='search'&&r.id){state.selected.clear();state.selected.add(r.id);}render();if(r.view==='collection')refreshSources(r.id);$('main').focus({preventScroll:true});window.scrollTo(0,0);});
try{for(const job of JSON.parse(sessionStorage.getItem('agentic-rag-job-links')||'[]'))if(job.id){state.jobs.set(job.id,{...job,status:'loading'});pollJob(job.id);}}catch{}
if(route().view==='search'&&route().id)state.selected.add(route().id);
render();refreshCollections({renderView:true});if(route().view==='collection')refreshSources(route().id);
async function status(){try {const data=await api('/api/status');$('connection').textContent=data.status==='ok'||data.status==='ready'?'Connected':data.status?String(data.status).replaceAll('_',' '):'Connected';$('connection').title='Application API status';}catch{$('connection').textContent='Connection unavailable';}}
status();setInterval(()=>{if(!document.hidden){refreshCollections();status();if(route().view==='collection'&&(sourcePending.has(route().id)||(state.sources.get(route().id)||[]).some(source=>source.schedule?.enabled&&!source.paused&&source.next_fire&&new Date(source.next_fire).getTime()<=Date.now())))refreshSources(route().id);}},8000);
